D += [decision(r['candidate_id'],'included','The reference explicitly connects actual robot work replacement to ongoing human material dependence/support.',r['source_ids'],society_id=r['id']) for r in R]
D.append(short_disposition('c0768','duplicate','Mechanismo is a robot-policing program inside the retained Mega-City One economy.',[P+'mechanismo'],
 'Supplementing human Judges does not establish a different population-wide material allocation system or general AI sovereignty.',duplicate_of='judge-dredd-mega-city-one'))
